顺序栈的操作:
#include <stdio.h>
#include <stdlib.h>

#define MAXSIZE 100

typedef struct {
    int data[MAXSIZE];
    int top;
} Stack;

// 初始化栈
void initStack(Stack *s) {
    s->top = -1;
}

// 入栈
int push(Stack *s, int x) {
    if (s->top >= MAXSIZE - 1) return 0;
    s->data[++s->top] = x;
    return 1;
}

// 出栈
int pop(Stack *s, int *x) {
    if (s->top < 0) return 0;
    *x = s->data[s->top--];
    return 1;
}

int main() {
    Stack s;
    initStack(&s);

    int num;
    while (scanf("%d", &num) && num != 0) {
        push(&s, num);
    }

    int first = 1;
    while (s.top >= 0) {
        int x;
        pop(&s, &x);
        if (!first) printf(" ");
        printf("%d", x);
        first = 0;
    }
    printf("\n");

    return 0;
}

