队列的基本操作:
#include <stdio.h>
#define MAXSIZE 100

typedef struct {
    int data[MAXSIZE];
    int front, rear;
} Queue;

void initQueue(Queue *q) { q->front = q->rear = 0; }
int enqueue(Queue *q, int x) {
    if ((q->rear + 1) % MAXSIZE == q->front) return 0;
    q->data[q->rear] = x;
    q->rear = (q->rear + 1) % MAXSIZE;
    return 1;
}
int dequeue(Queue *q, int *x) {
    if (q->front == q->rear) return 0;
    *x = q->data[q->front];
    q->front = (q->front + 1) % MAXSIZE;
    return 1;
}

