struct CircularQueue {
    vector<int> data;
    int head, tail, cap;
    CircularQueue(int n=200005): data(n), head(0), tail(0), cap(n) {}
    bool empty() { return head == tail; }
    bool push(int x) { int nxt = (tail + 1) % cap; if (nxt == head) return false; data[tail] = x; tail = nxt; return true; }
    bool pop(int &x) { if (empty()) return false; x = data[head]; head = (head + 1) % cap; return true; }
};

